<?php
namespace ServSys\Admin;
use ServSys\FlatRate\FlatRateCategoryRepository;
use ServSys\FlatRate\FlatRateConfigRepository;
use ServSys\FlatRate\FlatRateItemRepository;
use ServSys\FlatRate\FlatRateMaterialRepository;
use ServSys\FlatRate\FlatRateService;
use ServSys\Inventory\InventoryItemRepository;
use ServSys\Users\Capabilities;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class FlatRatePage {
 public function register(): void {add_action('admin_menu',array($this,'register_menu'));add_action('admin_post_servsys_save_flat_rate_config',array($this,'save_config'));add_action('admin_post_servsys_save_flat_rate_category',array($this,'save_category'));add_action('admin_post_servsys_save_flat_rate_item',array($this,'save_item'));}
 public function register_menu(): void {add_submenu_page(null,'Flat Rate Pricing','Flat Rate Pricing',Capabilities::VIEW_FLAT_RATE,'servsys-flat-rate',array($this,'render'));}
 public function render(): void {if(!current_user_can(Capabilities::VIEW_FLAT_RATE)){wp_die(esc_html__('You do not have permission to view Flat Rate pricing.','servsys'));}/* phpcs:disable WordPress.Security.NonceVerification.Recommended -- Read-only admin navigation/search. */\n$tab=isset($_GET['tab'])?sanitize_key(wp_unslash($_GET['tab'])):'items';$edit=isset($_GET['edit'])?absint(wp_unslash($_GET['edit'])):0;$term=isset($_GET['s'])?sanitize_text_field(wp_unslash($_GET['s'])):'';$error=isset($_GET['servsys_error'])?sanitize_text_field(wp_unslash($_GET['servsys_error'])):'';\n/* phpcs:enable WordPress.Security.NonceVerification.Recommended */echo '<div class="wrap"><h1>ServSys Flat Rate Pricing</h1>';if($error){echo '<div class="notice notice-error inline"><p>'.esc_html($error).'</p></div>';}echo '<nav class="nav-tab-wrapper">';foreach(array('items'=>'Price Book','categories'=>'Categories','config'=>'Pricing Configuration') as $key=>$label){echo '<a class="nav-tab '.($tab===$key?'nav-tab-active':'').'" href="'.esc_url(admin_url('admin.php?page=servsys-flat-rate&tab='.$key)).'">'.esc_html($label).'</a>';}echo '</nav>';if('config'===$tab){$this->render_config();}elseif('categories'===$tab){$this->render_categories($edit);}else{$this->render_items($edit,$term);}echo '</div>';}
 private function render_config(): void {$c=(new FlatRateConfigRepository())->current()?:array();$c=wp_parse_args($c,array('labor_rate'=>0,'additional_repair_multiplier'=>1,'agreement_repair_multiplier'=>1,'commercial_multiplier'=>1,'part_markup_multiplier'=>1,'sales_tax_percent'=>0,'special_item_low_price'=>0,'special_item_high_price'=>0,'special_item_high_hours'=>0));echo '<h2>Pricing Configuration</h2><p>These company-specific values feed the Flat Rate pricing engine. Agreement pricing eligibility is determined separately; this screen only stores its multiplier.</p>';if(!current_user_can(Capabilities::MANAGE_FLAT_RATE)){return;}echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_save_flat_rate_config');echo '<input type="hidden" name="action" value="servsys_save_flat_rate_config">';foreach(array('labor_rate'=>'Labor Rate','additional_repair_multiplier'=>'Additional Repair Multiplier','agreement_repair_multiplier'=>'Agreement Repair Multiplier','commercial_multiplier'=>'Commercial Multiplier','part_markup_multiplier'=>'Parts Markup Multiplier','sales_tax_percent'=>'Sales Tax Percent','special_item_low_price'=>'Special Item Low Price','special_item_high_price'=>'Special Item High Price','special_item_high_hours'=>'Special Item High Hours') as $key=>$label){echo '<p><label>'.esc_html($label).'<br><input type="number" min="0" step="0.0001" name="'.esc_attr($key).'" value="'.esc_attr((string)$c[$key]).'" required></label></p>';}submit_button('Save Flat Rate Configuration');echo '</form>';}
 private function render_categories(int $edit): void {$repo=new FlatRateCategoryRepository();$editing=$edit?$repo->find($edit):null;echo '<h2>Categories</h2><table class="widefat striped"><thead><tr><th>Name</th><th>Sort</th><th>Status</th><th>Action</th></tr></thead><tbody>';foreach($repo->all(true) as $row){echo '<tr><td>'.esc_html($row['name']).'</td><td>'.esc_html($row['sort_order']).'</td><td>'.($row['active']?'Active':'Inactive').'</td><td>';if(current_user_can(Capabilities::MANAGE_FLAT_RATE)){echo '<a class="button button-small" href="'.esc_url(admin_url('admin.php?page=servsys-flat-rate&tab=categories&edit='.(int)$row['id'])).'">Edit</a>';}echo '</td></tr>';}echo '</tbody></table>';if(!current_user_can(Capabilities::MANAGE_FLAT_RATE)){return;}$editing=wp_parse_args($editing?:array(),array('id'=>0,'name'=>'','sort_order'=>0,'active'=>1));echo '<h2>'.($editing['id']?'Edit':'Add').' Category</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_save_flat_rate_category');echo '<input type="hidden" name="action" value="servsys_save_flat_rate_category"><input type="hidden" name="category_id" value="'.esc_attr((string)$editing['id']).'"><p><label>Name<br><input class="regular-text" name="name" value="'.esc_attr($editing['name']).'" required></label></p><p><label>Sort Order<br><input type="number" name="sort_order" value="'.esc_attr((string)$editing['sort_order']).'"></label></p><p><label><input type="checkbox" name="active" value="1" '.checked((int)$editing['active'],1,false).'> Active</label></p>';submit_button($editing['id']?'Save Category':'Add Category');echo '</form>';}
 private function render_items(int $edit,string $term): void {$repo=new FlatRateItemRepository();$categories=new FlatRateCategoryRepository();$catmap=array();foreach($categories->all(true) as $cat){$catmap[(int)$cat['id']]=$cat['name'];}echo '<h2>Price Book</h2><form method="get"><input type="hidden" name="page" value="servsys-flat-rate"><input type="hidden" name="tab" value="items"><p class="search-box"><input type="search" name="s" value="'.esc_attr($term).'"> ';submit_button('Search Flat Rate','secondary','',false);echo '</p></form><table class="widefat striped"><thead><tr><th>Code</th><th>Description</th><th>Category</th><th>Hours</th><th>Status</th><th>Action</th></tr></thead><tbody>';foreach($repo->search($term,true) as $row){echo '<tr><td>'.esc_html($row['code']).'</td><td>'.esc_html($row['description']).'</td><td>'.esc_html($catmap[(int)$row['category_id']]??'').'</td><td>'.esc_html($row['labor_hours']).'</td><td>'.($row['active']?'Active':'Inactive').'</td><td>';if(current_user_can(Capabilities::MANAGE_FLAT_RATE)){echo '<a class="button button-small" href="'.esc_url(admin_url('admin.php?page=servsys-flat-rate&tab=items&edit='.(int)$row['id'])).'">Edit</a>';}echo '</td></tr>';}echo '</tbody></table>';if(!current_user_can(Capabilities::MANAGE_FLAT_RATE)){return;}$item=$edit?$repo->find($edit):null;$item=wp_parse_args($item?:array(),array('id'=>0,'code'=>'','description'=>'','category_id'=>0,'customer_notes'=>'','labor_hours'=>0,'no_discount'=>0,'special_item'=>0,'active'=>1));echo '<h2>'.($item['id']?'Edit':'Add').' Flat Rate Item</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_save_flat_rate_item');echo '<input type="hidden" name="action" value="servsys_save_flat_rate_item"><input type="hidden" name="item_id" value="'.esc_attr((string)$item['id']).'"><p><label>Code<br><input type="number" min="1" name="code" value="'.esc_attr((string)$item['code']).'" required></label></p><p><label>Description<br><input class="regular-text" name="description" value="'.esc_attr($item['description']).'" required></label></p><p><label>Category<br><select name="category_id"><option value="0">None</option>';foreach($categories->all(true) as $cat){echo '<option value="'.esc_attr((string)$cat['id']).'" '.selected((int)$item['category_id'],(int)$cat['id'],false).'>'.esc_html($cat['name']).'</option>';}echo '</select></label></p><p><label>Labor Hours<br><input type="number" min="0" step="0.0001" name="labor_hours" value="'.esc_attr((string)$item['labor_hours']).'" required></label></p><p><label>Customer Notes<br><textarea class="large-text" rows="3" name="customer_notes">'.esc_textarea($item['customer_notes']).'</textarea></label></p><p><label><input type="checkbox" name="no_discount" value="1" '.checked((int)$item['no_discount'],1,false).'> No discount / fixed material-price behavior</label><br><label><input type="checkbox" name="special_item" value="1" '.checked((int)$item['special_item'],1,false).'> Special item</label><br><label><input type="checkbox" name="active" value="1" '.checked((int)$item['active'],1,false).'> Active</label></p>';$this->render_materials((int)$item['id']);submit_button($item['id']?'Save Flat Rate Item':'Add Flat Rate Item');echo '</form>';}
 private function render_materials(int $item_id): void {$existing=$item_id?(new FlatRateMaterialRepository())->for_item($item_id):array();while(count($existing)<5){$existing[]=array('inventory_item_id'=>0,'quantity'=>1,'manual_description'=>'','manual_unit_cost'=>'');}$inventory=(new InventoryItemRepository())->search('',true);echo '<h3>Material Recipe</h3><p>Use an inventory item or a manual material description on each row. Additional rows can be added by saving and editing again.</p><table class="widefat"><thead><tr><th>Inventory Item</th><th>Qty</th><th>Manual Description</th><th>Manual Unit Cost</th></tr></thead><tbody>';foreach($existing as $i=>$row){echo '<tr><td><select name="materials['.esc_attr((string)$i).'][inventory_item_id]"><option value="0">Manual / None</option>';foreach($inventory as $inv){echo '<option value="'.esc_attr((string)$inv['id']).'" '.selected((int)($row['inventory_item_id']??0),(int)$inv['id'],false).'>'.esc_html($inv['sku'].' — '.$inv['description']).'</option>';}echo '</select></td><td><input type="number" min="0.0001" step="0.0001" name="materials['.esc_attr((string)$i).'][quantity]" value="'.esc_attr((string)($row['quantity']??1)).'"></td><td><input name="materials['.esc_attr((string)$i).'][manual_description]" value="'.esc_attr($row['manual_description']??'').'"></td><td><input type="number" min="0" step="0.0001" name="materials['.esc_attr((string)$i).'][manual_unit_cost]" value="'.esc_attr((string)($row['manual_unit_cost']??'')).'"></td></tr>';}echo '</tbody></table>';}
 // phpcs:ignore WordPress.Security.NonceVerification.Missing -- guard() verifies the action-specific nonce before request data is used.
 public function save_config(): void {$this->guard('servsys_save_flat_rate_config');$this->run_save(function(){(new FlatRateService())->save_config(wp_unslash($_POST));},'config');}
 // phpcs:ignore WordPress.Security.NonceVerification.Missing -- guard() verifies the action-specific nonce before request data is used.
 public function save_category(): void {$this->guard('servsys_save_flat_rate_category');$id=isset($_POST['category_id'])?absint(wp_unslash($_POST['category_id'])):0;$this->run_save(function()use($id){(new FlatRateService())->save_category(wp_unslash($_POST),$id);},'categories');}
 // phpcs:ignore WordPress.Security.NonceVerification.Missing, WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- guard() verifies nonce; nested material rows are validated by FlatRateService.
 public function save_item(): void {$this->guard('servsys_save_flat_rate_item');$id=isset($_POST['item_id'])?absint(wp_unslash($_POST['item_id'])):0;$this->run_save(function()use($id){$service=new FlatRateService();$saved=$service->save_item(wp_unslash($_POST),$id);$service->replace_materials($saved,isset($_POST['materials'])?(array)wp_unslash($_POST['materials']):array());},'items');}
 private function guard(string $nonce): void {check_admin_referer($nonce);if(!current_user_can(Capabilities::MANAGE_FLAT_RATE)){wp_die(esc_html__('Permission denied.','servsys'));}}
 private function run_save(callable $callback,string $tab): void {try{$callback();$url=admin_url('admin.php?page=servsys-flat-rate&tab='.$tab);}catch(\InvalidArgumentException|\RuntimeException $e){$url=add_query_arg('servsys_error',$e->getMessage(),admin_url('admin.php?page=servsys-flat-rate&tab='.$tab));}wp_safe_redirect($url);exit;}
}
